var cells = map[[2]int][]*Entity{}
func key(x, y float64) [2]int { return [2]int{int(x / 32), int(y / 32)} }
func insert(e *Entity) { k := key(e.X, e.Y); cells[k] = append(cells[k], e) }
func near(x, y, r float64) (out []*Entity) {
    lo, hi := key(x-r, y-r), key(x+r, y+r)
    for cy := lo[1]; cy <= hi[1]; cy++ {
        for cx := lo[0]; cx <= hi[0]; cx++ {
            out = append(out, cells[[2]int{cx, cy}]...)
        }
    }
    return out
}
